import type { DesignContent } from "@/lib/design-content";

export const content: DesignContent = {"slug": "create-account", "title": "Create account · UniShare", "css": "\n:root{--teal:#0f6b63;--ink:#171c1b;--muted:#4b5552;--line:#111;--field:#f5f7f6}\n*{box-sizing:border-box;margin:0;padding:0}\nbody{font-family:\"DM Sans\",system-ui,sans-serif;color:var(--ink);background:#fff;line-height:1.5;min-height:100vh;display:flex;flex-direction:column}\na{text-decoration:none;color:inherit}\n.wrap{width:100%;max-width:1000px;margin:0 auto;padding:0 24px}\n.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:11px 20px;border-radius:6px;font-size:15px;font-weight:500;border:1.5px solid var(--teal);background:var(--teal);color:#fff;cursor:pointer;white-space:nowrap;font-family:inherit}\n.btn.block{width:100%;padding:14px;font-size:16px}\n.btn.sm{padding:9px 16px;font-size:14px}\nheader{border-bottom:1.5px solid var(--line)}\nheader .wrap{display:flex;justify-content:space-between;align-items:center;height:68px}\n.logo{display:flex;align-items:center;gap:8px;font-weight:700;font-size:18px}\nnav{display:flex;align-items:center;gap:24px;font-size:14px}\nnav .link{color:var(--teal);font-weight:500}\n\n.steps{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:36px 0 32px}\n.step{display:flex;align-items:center;gap:10px;font-size:14px;color:var(--muted)}\n.dot{width:26px;height:26px;border-radius:50%;border:1.5px solid #9aa6a3;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:500;color:var(--muted);background:#fff}\n.step.on{color:var(--teal);font-weight:700}\n.step.on .dot{background:var(--teal);border-color:var(--teal);color:#fff}\n\n.main{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:start;padding-bottom:56px}\n.eyebrow{font-size:12px;font-weight:700;letter-spacing:.06em;color:var(--teal);text-transform:uppercase}\nh1{font-size:44px;line-height:1.1;font-weight:700;letter-spacing:-.02em;margin:12px 0 18px}\nh1 em{font-style:normal;color:var(--teal)}\n.lead{color:var(--muted);font-size:16px;max-width:400px}\n.arch{width:100%;max-width:310px;aspect-ratio:4/4.6;margin-top:36px;border:1.5px solid var(--line);border-radius:160px 160px 10px 10px;box-shadow:8px 8px 0 var(--teal);overflow:hidden}\n.arch img{width:100%;height:100%;object-fit:cover;display:block}\n.caption{font-size:13px;color:var(--muted);margin-top:18px;max-width:320px}\n\n.card{position:relative;border:1.5px solid var(--line);border-radius:12px;padding:36px 36px 30px;box-shadow:8px 8px 0 var(--teal);background:#fff}\n.card h2{font-size:30px;font-weight:700;letter-spacing:-.01em}\n.card .sub{color:var(--muted);font-size:15px;margin:8px 0 26px}\nlabel{display:block;font-size:14px;font-weight:700;margin-bottom:8px}\n.field{margin-bottom:20px}\n.input{position:relative}\n.input input{width:100%;height:48px;padding:0 44px 0 14px;border:1.5px solid var(--line);border-radius:6px;background:var(--field);font:inherit;font-size:15px;color:var(--ink)}\n.input input::placeholder{color:#7d8784}\n.input input:focus{outline:2px solid var(--teal);outline-offset:1px}\n.input svg{position:absolute;right:14px;top:50%;transform:translateY(-50%);width:18px;height:18px;stroke:var(--ink);fill:none;stroke-width:1.8}\n.hint{font-size:12.5px;color:var(--muted);margin-top:7px}\n.agree{display:flex;align-items:center;gap:10px;font-size:13.5px;color:var(--muted);margin:4px 0 22px}\n.agree input{width:18px;height:18px;accent-color:var(--teal)}\n.agree a,.fine a,.already a{color:var(--teal);font-weight:700}\n.btn.block{margin-bottom:16px}\n.fine{text-align:center;font-size:13px;color:var(--muted);margin-bottom:14px}\n.already{text-align:center;font-size:14px;color:var(--muted)}\n\nfooter{border-top:1.5px solid var(--line);padding:22px 0}\nfooter .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;font-size:13px;color:var(--muted)}\nfooter .links{display:flex;gap:24px;color:var(--teal);font-weight:700}\n\n@media (max-width:820px){\n  .main{grid-template-columns:1fr;gap:48px}\n  h1{font-size:36px}\n  .arch{margin:28px auto 0}\n  .caption{margin:18px auto 0;text-align:center}\n  .intro{text-align:center}\n  .lead{margin:0 auto}\n  .steps{justify-content:flex-start}\n}\n@media (max-width:480px){\n  .card{padding:28px 22px}\n  .card h2{font-size:26px}\n  .step span.lbl{display:none}\n}\n", "body": "\n\n<header>\n  <div class=\"wrap\">\n    <a class=\"logo\" href=\"/\">\n      <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#0f6b63\" stroke-width=\"2\"><circle cx=\"8\" cy=\"12\" r=\"5\"/><circle cx=\"16\" cy=\"12\" r=\"5\"/></svg>\n      UniShare\n    </a>\n    <nav>\n      <a class=\"link\" href=\"/log-in\">Log in</a>\n      <a class=\"btn sm\" href=\"/create-account\">Create account</a>\n    </nav>\n  </div>\n</header>\n\n<main class=\"wrap\">\n  <div class=\"steps\" aria-label=\"Progress\">\n    <div class=\"step on\"><span class=\"dot\">1</span><span class=\"lbl\">Create account</span></div>\n    <div class=\"step\"><span class=\"dot\">2</span><span class=\"lbl\">Confirm email</span></div>\n    <div class=\"step\"><span class=\"dot\">3</span><span class=\"lbl\">Student verification</span></div>\n    <div class=\"step\"><span class=\"dot\">4</span><span class=\"lbl\">Review pending</span></div>\n  </div>\n\n  <div class=\"main\">\n    <section class=\"intro\">\n      <p class=\"eyebrow\">Your campus. Your community.</p>\n      <h1>A shared shelf.<br><em>A familiar campus.</em></h1>\n      <p class=\"lead\">Borrow what you need, lend what you have, and share a ride with students from your own university.</p>\n      <div class=\"arch\"><img src=\"data:image/jpeg;base64,\" alt=\"Student standing on a campus path\"></div>\n      <p class=\"caption\">Real students. University email. A little more trust.</p>\n    </section>\n\n    <section class=\"card\">\n      <h2>Create your account</h2>\n      <p class=\"sub\">Your university email is your way in. Let’s start there.</p>\n\n      <form onsubmit=\"return false\">\n        <div class=\"field\">\n          <label for=\"email\">University email</label>\n          <div class=\"input\">\n            <input id=\"email\" type=\"email\" placeholder=\"e.g. farhana@std.du.ac.bd\" autocomplete=\"email\">\n            <svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"1.5\"/><path d=\"M3 6l9 7 9-7\"/></svg>\n          </div>\n          <p class=\"hint\">Only students with a university email can join.</p>\n        </div>\n\n        <div class=\"field\">\n          <label for=\"pw\">Password</label>\n          <div class=\"input\">\n            <input id=\"pw\" type=\"password\" placeholder=\"Create a password\" autocomplete=\"new-password\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M3 3l18 18M10.6 6.1A9.8 9.8 0 0 1 12 6c5 0 8.5 4.5 9.5 6-.4.7-1.1 1.7-2.1 2.7M6.6 6.7C4.3 8.2 2.8 10.3 2.5 12c1 1.5 4.5 6 9.5 6 1.5 0 2.9-.4 4.1-1\"/><path d=\"M9.9 9.9a3 3 0 0 0 4.2 4.2\"/></svg>\n          </div>\n          <p class=\"hint\">Use at least 8 characters, including a letter and a number.</p>\n        </div>\n\n        <div class=\"field\">\n          <label for=\"pw2\">Confirm password</label>\n          <div class=\"input\">\n            <input id=\"pw2\" type=\"password\" placeholder=\"Re-enter your password\" autocomplete=\"new-password\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M3 3l18 18M10.6 6.1A9.8 9.8 0 0 1 12 6c5 0 8.5 4.5 9.5 6-.4.7-1.1 1.7-2.1 2.7M6.6 6.7C4.3 8.2 2.8 10.3 2.5 12c1 1.5 4.5 6 9.5 6 1.5 0 2.9-.4 4.1-1\"/><path d=\"M9.9 9.9a3 3 0 0 0 4.2 4.2\"/></svg>\n          </div>\n        </div>\n\n        <label class=\"agree\" style=\"font-weight:400\">\n          <input type=\"checkbox\">\n          <span>I agree to the <a href=\"/terms\">Terms of use</a> and <a href=\"/privacy\">Privacy policy</a>.</span>\n        </label>\n\n        <button class=\"btn block\" type=\"submit\">Create account\n          <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2.2\"><path d=\"M5 12h14M13 6l6 6-6 6\"/></svg>\n        </button>\n\n        <p class=\"fine\">We’ll send a 6-digit code to confirm your email.</p>\n        <p class=\"already\">Already have an account? <a href=\"/log-in\">Log in</a></p>\n      </form>\n    </section>\n  </div>\n</main>\n\n<footer>\n  <div class=\"wrap\">\n    <span>UniShare. Made for university students in Bangladesh.</span>\n    <span class=\"links\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/get-help\">Get help</a></span>\n  </div>\n</footer>\n\n", "scripts": [], "fonts": ["https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;700&display=swap"]};

